window.BABA = window.BABA || {};
window.BABA.Narration = {"questNames":{"text":"Hücreler açıldı. Tutsaklar nakil yolunu gösteriyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.016,"audio":"","chapter":1},"questVerdict":{"text":"Esirlerin zincirleri kırıldı. Kıyıya çıkan yolu mezarın gardiyanı tutuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.048,"audio":"","chapter":1},"questBell":{"text":"Gemideki esirler serbest. Çanın emri artık geçmiyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.136,"audio":"","chapter":2},"questMemory":{"text":"Kara sevkiyat durdu. Harabelere giden yol ortaya çıktı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.208,"audio":"","chapter":2},"questKing":{"text":"Kurbanların bağları çözüldü. Taşın içindeki sesler susuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.424,"audio":"","chapter":3},"questEcho":{"text":"Mağara geçidi açıldı. Ocağa giden yolu buldun.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.632,"audio":"","chapter":3},"questPrisoner":{"text":"Ocaktaki tutsaklar serbest. Artık ateşi beslemeyecekler.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.76,"audio":"","chapter":4},"questHeart":{"text":"Son kapının düzeneği senin elinde. Mahkemeye ilerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.208,"audio":"","chapter":4},"ruinsIntro":{"text":"Kadı’nın kurtuluş dediği yer burası. Kurbanlar ölemiyor. Toprak onları bağlı tutuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.136,"audio":"","chapter":3},"ruinsCheckpoint":{"text":"Taş güvenli. Mağaranın son geçidine ilerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.488,"audio":"","chapter":3},"ruinsBoss":{"text":"Kurban Bekçisi, Kadı’nın yolunu koruyor. Onu aş.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.616,"audio":"","chapter":3},"ruinsWin":{"text":"Bekçi düştü. Mağaranın altından ocağın sıcaklığı geliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.256,"audio":"","chapter":3},"forgeIntro":{"text":"Burada gardiyanların silahları, esirlerin zincirleri dövülüyor. Kadı’nın ocağına geldin.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.08,"audio":"","chapter":4},"forgeCheckpoint":{"text":"Közlerin uzağında soluklan. Ocağın ustası son kapıyı tutuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.712,"audio":"","chapter":4},"forgeBoss":{"text":"Ocağın Ustası geliyor. Bu kez kendi demiriyle yüzleşecek.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.4,"audio":"","chapter":4},"forgeWin":{"text":"Ocak sustu. Zincir üretimi durdu. Son Mahkeme’ye giden yol açık.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.44,"audio":"","chapter":4},"coastIntro":{"text":"Bu limanın yükü insan. Kadı’nın gemileri esirleri buraya getiriyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.64,"audio":"","chapter":2},"coastRoots":{"text":"Kökler, kıyıya gömülen kurbanlara dolanmış. Toprak onları bırakmıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.216,"audio":"","chapter":2},"coastStreet":{"text":"Evler boşaltılmış. Kapılarda esirlerin sayıldığı işaretler var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.856,"audio":"","chapter":2},"coastPier":{"text":"Fenerler kurban gemilerine yol gösteriyor. İçeride yaşayanlar var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.928,"audio":"","chapter":2},"coastSquare":{"text":"Meydanın altında isimsiz mezarlar var. Liman efendisi sayıları biliyor. İsimleri değil.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.88,"audio":"","chapter":2},"coastCheckpoint":{"text":"Fenerin yanında soluklan. Çanlığa giden yol açık.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.68,"audio":"","chapter":2},"coastBoss":{"text":"Liman efendisi çanıyla avcılarını çağırıyor. Çanı sustur.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.304,"audio":"","chapter":2},"coastDeath":{"text":"Deniz seni almadı. Kıyıya dön ve ayağa kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.344,"audio":"","chapter":2},"coastDeath2":{"text":"Kökler seni tutamadı. Yeniden yürü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.104,"audio":"","chapter":2},"coastDeath3":{"text":"Çan hâlâ çalıyor. Bu kıyıda kalmayacaksın.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.704,"audio":"","chapter":2},"coastSeal":{"text":"Nakil yolu açılıyor. Kıyının içlerine ilerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.536,"audio":"","chapter":2},"coastWin":{"text":"Çan sustu. Esirlerin nakli durdu. Kadı’ya giden yol harabelerden geçiyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.656,"audio":"","chapter":2},"intro":{"text":"Seni canlı gömdüler, Bahtiyar. Taş kapağı kırdın. Şimdi tutsakların zincirlerini kır ve bu mezardan çık.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.696,"audio":"","chapter":1},"chains":{"text":"Bu zincirlerin ucunda hâlâ yaşayan insanlar var. Hücreleri aç.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.976,"audio":"","chapter":1},"ritual":{"text":"Yaralıları tedavi etmek için getirmemişler. Acıları, Kadı’nın ayinini besliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.96,"audio":"","chapter":1},"crypt":{"text":"Sunak hâlâ sıcak. Bu mezar, kurbanların ilk durağı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.592,"audio":"","chapter":1},"rot":{"text":"Kemikler duvarlara örülmüş. Kadı, ölülerini bile serbest bırakmıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.976,"audio":"","chapter":1},"checkpoint":{"text":"Taşın yanında soluklan. Yolun henüz bitmedi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.56,"audio":"","chapter":1},"boss":{"text":"Mezar Gardiyanı geçidi tutuyor. Limana giden yol onun ardında.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.808,"audio":"","chapter":1},"heroOath":{"text":"Beni gömdünüz. Şimdi sıra sizde.","speaker":"Bahtiyar","voice":"tr-TR-AhmetNeural","style":"D","duration":3.792,"audio":"","chapter":1},"cellat":{"text":"Kadı seni canlı istiyor. Yeniden tabutuna gireceksin.","speaker":"Mezar Gardiyanı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.304,"audio":"","chapter":1},"seal":{"text":"Bir zincir daha kırıldı. İlerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.792,"audio":"","chapter":1},"death":{"text":"Nefesin hâlâ var. Ayağa kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.696,"audio":"","chapter":1},"death2":{"text":"Bu mezar seni tutamayacak. Yeniden dene.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.44,"audio":"","chapter":1},"death3":{"text":"Taş kapağı kırdın. Burada pes etme.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.104,"audio":"","chapter":1},"win":{"text":"Gardiyan düştü. Esirlerin götürüldüğü limana giden yol açıldı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":5.616,"audio":"","chapter":1}};
